import { Kafka } from 'kafkajs';

const kafka = new Kafka({ brokers: ['kafka-broker-1:9092', 'kafka-broker-2:9092'] });
const admin = kafka.admin();

export async function provisionTopic(topicName: string) {
  await admin.connect();
  await admin.createTopics({
    topics: [{
      topic: topicName,
      numPartitions: 12,        // Scaled to match target consumer concurrency
      replicationFactor: 3,    // Multi-AZ fault tolerance
      configEntries: [
        { name: 'cleanup.policy', value: 'delete' },
        { name: 'retention.ms', value: '604800000' }, // 7 Days retention
        { name: 'min.insync.replicas', value: '2' },   // Enforce durable consensus
      ]
    }]
  });
  await admin.disconnect();
}

export async function routeToDlq(
  producer: Producer,
  msg: KafkaMessage,
  originalTopic: string,
  partition: number,
  error: Error
) {
  await producer.send({
    topic: `${originalTopic}-dlq`,
    messages: [{
      key: msg.key,
      value: msg.value,
      headers: {
        ...msg.headers,
        'x-original-topic': originalTopic,
        'x-original-partition': String(partition),
        'x-original-offset': msg.offset,
        'x-failed-at': new Date().toISOString(),
        'x-exception-name': error.name,
        'x-exception-message': error.message,
      }
    }]
  });
}

export async function consumeWithBackpressure(consumer: Consumer, dbPool: Pool) {
  await consumer.run({
    eachBatch: async ({ batch, pause, resolveOffset, heartbeat }) => {
      for (const message of batch.messages) {
        // If downstream DB pool is exhausted, pause fetching
        if (dbPool.waitingCount > 50) {
          console.warn('DB overloaded! Pausing consumption for 5 seconds...');
          const resume = pause();
          setTimeout(() => resume(), 5000);
          break; // Stop processing current batch
        }

        await processRecord(message);
        resolveOffset(message.offset);
        await heartbeat(); // Keep coordinator lease alive
      }
    }
  });
}

export function calculatePartitionCount(
  peakMbPerSec: number,
  producerMbPerSec = 30,
  consumerMbPerSec = 5,
  brokerCount = 6
): number {
  const neededForProducers = Math.ceil(peakMbPerSec / producerMbPerSec);
  const neededForConsumers = Math.ceil(peakMbPerSec / consumerMbPerSec);
  const rawPartitions = Math.max(neededForProducers, neededForConsumers);

  // Round up to nearest multiple of broker count for even distribution
  const balancedPartitions = Math.ceil(rawPartitions / brokerCount) * brokerCount;
  return Math.max(balancedPartitions, brokerCount);
}

