export async function handleConsumerMessage(msg: KafkaMessage) {
  const payload = JSON.parse(msg.value.toString());
  const retryCount = Number(msg.headers?.['x-retry-count'] || 0);

  try {
    await processOrderBusinessLogic(payload);
  } catch (err) {
    if (retryCount >= 3) {
      // Exhausted retries -> Route to DLQ
      await producer.send({
        topic: 'orders-dlq',
        messages: [{ ...msg, headers: { 'x-error': String(err) } }]
      });
    } else {
      // Route to next tiered delay topic
      const nextTopic = retryCount === 0 ? 'orders-retry-5s' : 'orders-retry-30s';
      await producer.send({
        topic: nextTopic,
        messages: [{
          ...msg,
          headers: { ...msg.headers, 'x-retry-count': String(retryCount + 1) }
        }]
      });
    }
  }
}
